<?php $items = is_array( $args['items'] ?? null ) ? $args['items'] : array(); ?>
<section class="dzn-tp-section" aria-labelledby="tp-calendar"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">نگاه پیش رو</p><h2 id="tp-calendar">تقویم کلاس‌های آینده</h2></div><div class="dzn-tp-actions"><button type="button" data-dzn-tp-presentation>روز قبل</button><button type="button" data-dzn-tp-presentation>هفتهٔ بعد</button></div></div><div class="dzn-tp-calendar" role="list"><?php foreach ( $items as $item ) : $valid = dzn_theme_teacher_portal_calendar_valid( $item ); ?><article role="listitem" class="is-<?php echo esc_attr( $valid ? $item['state'] : 'unknown' ); ?>"><p><?php echo esc_html( $valid ? $item['day'] : '' ); ?></p><time><?php echo esc_html( $valid ? $item['time'] : '' ); ?></time><strong><?php echo esc_html( $valid ? ( $item['label'] ?? '' ) : 'رویداد در دسترس نیست' ); ?></strong></article><?php endforeach; ?></div><p class="dzn-tp-help">رنگ‌ها همراه با عنوان نوشتاری‌اند و هیچ زمان‌بندی در پوسته محاسبه نمی‌شود.</p></section>
